data.minimal_example:
import 'package:fl_heatmap/fl_heatmap.dart';

Heatmap(
  heatmapData: HeatmapData(
    rows: ['2022','2021'],
    columns: ['Jan','Feb'],
    items: [
      for (var r in ['2022','2021'])
        for (var c in ['Jan','Feb'])
          HeatmapItem(value: 5.0, unit: 'kWh', xAxisLabel: c, yAxisLabel: r),
    ],
  ),
  onItemSelectedListener: (item) => print(item?.value),
);
